import { priceCart, Promotion } from '../src/pricing';

describe('regresión de cupón mínimo', () => {
  it('aplica el cupón cuando el subtotal descontado es exactamente igual a la compra mínima', () => {
    const promotions: Promotion[] = [
      { type: 'COUPON_FIXED', code: 'MINIMO', amountCents: 1000, minPurchaseCents: 5000 },
    ];

    const lines = [
      { sku: 'TEST', qty: 1, unitPriceCents: 5000, category: 'general' },
    ];

    const result = priceCart(lines, promotions, 'MINIMO');
    expect(result.discountCents).toBe(1000);
    expect(result.totalCents).toBe(4000);
  });
});
